using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class B2Repair {
 public static object RenderReset(){var pipeline=GraphicsSettings.currentRenderPipeline;var m=typeof(RenderPipelineManager).GetMethod("CleanupRenderPipeline",BindingFlags.NonPublic|BindingFlags.Static);if(m==null)throw new Exception("No cleanup API");m.Invoke(null,null);EditorApplication.QueuePlayerLoopUpdate();SceneView.RepaintAll();return new{asset=pipeline?pipeline.name:null,reset=true};}
 public static object Meshes(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");var mfs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).ToArray();int fixedMeshes=0,removed=0;foreach(var m in mfs.Where(f=>f.sharedMesh&&f.sharedMesh.isReadable).Select(f=>f.sharedMesh).Distinct().ToArray()){var vv=m.vertices;var arrays=new System.Collections.Generic.List<int[]>();int bad=0;for(int j=0;j<m.subMeshCount;j++){var src=m.GetTriangles(j);var dst=new System.Collections.Generic.List<int>();for(int i=0;i<src.Length;i+=3){if(Vector3.Cross(vv[src[i+1]]-vv[src[i]],vv[src[i+2]]-vv[src[i]]).sqrMagnitude<1e-16f){bad++;continue;}dst.Add(src[i]);dst.Add(src[i+1]);dst.Add(src[i+2]);}arrays.Add(dst.ToArray());}if(bad==0)continue;var clean=UnityEngine.Object.Instantiate(m);clean.name="BC_Clean_"+m.name;for(int j=0;j<arrays.Count;j++)clean.SetTriangles(arrays[j],j);clean.RecalculateBounds();AssetDatabase.CreateAsset(clean,"Assets/Afrer_Seconds/05.Model/"+(m.name.Contains("Reactor")?"Props":"Environment")+"/B2/"+clean.name+".asset");foreach(var f in mfs.Where(f=>f.sharedMesh==m)){f.sharedMesh=clean;var c=f.GetComponent<MeshCollider>();if(c)c.sharedMesh=clean;PrefabUtility.RecordPrefabInstancePropertyModifications(f);}removed+=bad;fixedMeshes++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{fixedMeshes,removed};}
}
